package com.sih.hr.controller;
import com.sih.hr.dto.HrDtos.*; import com.sih.hr.service.HrWorkflowService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/hr") public class HrController { private final HrWorkflowService service; public HrController(HrWorkflowService service){this.service=service;} @GetMapping("/staff") public List<StaffResponse> staff(){return service.listStaff();} @PostMapping("/staff") @ResponseStatus(HttpStatus.CREATED) public StaffResponse createStaff(@Valid @RequestBody CreateStaffRequest r){return service.createStaff(r);}@GetMapping("/credentials") public List<CredentialResponse> credentials(){return service.listCredentials();}@PostMapping("/credentials") @ResponseStatus(HttpStatus.CREATED) public CredentialResponse createCredential(@Valid @RequestBody CreateCredentialRequest r){return service.createCredential(r);}@PostMapping("/credentials/{id}/renew") public CredentialResponse renew(@PathVariable Long id,@Valid @RequestBody RenewCredentialRequest r){return service.renewCredential(id,r);}@GetMapping("/shifts") public List<ShiftResponse> shifts(){return service.listShifts();}@PostMapping("/shifts") @ResponseStatus(HttpStatus.CREATED) public ShiftResponse createShift(@Valid @RequestBody CreateShiftRequest r){return service.createShift(r);}@PostMapping("/shifts/{id}/publish") public ShiftResponse publish(@PathVariable Long id){return service.publishShift(id);}@PostMapping("/shifts/{id}/cancel") public ShiftResponse cancel(@PathVariable Long id){return service.cancelShift(id);} }
